	def createMarker(latitude, longitude, tooltip):
		if latitude is None or longitude is None: return {}
		return	{
				  "geometry": {"coordinates": [float(longitude), float(latitude)], "type": "Point"},
				  "marker": {
				    "icon": {"color": "blue", "path": "material/location_on", "size": {"height": 50, "width": 50}},
				    "tooltip": {"content": {"text": tooltip}
				    }
				  },
				  "properties": {}, "type": "Feature"
				}

	markers = []

	chkShtIds = list(set([chkShtEvent['chkShtId'] for chkShtEvent in value]))

	chkItemIds = []
	for chkShtId in chkShtIds:
		chkItems = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.quality.config.getChecks({'chkShtId': chkShtId, 'dataTypeName': 'Geo Location', 'enabled': True}))
		chkItemIds += [chkItem['chkItemId'] for chkItem in chkItems]

	for chkShtEvent in value:
		for chkItemId in chkItemIds:
			chkItemEvent = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.quality.event.getChkShtItemEventValues(chkShtEvent['chkShtEventId'], chkItemId),0)
			if chkItemEvent['chkItemValue'] is None:continue
			try:
				info = system.util.jsonDecode(chkItemEvent['chkItemValue'])
				tooltip = "Check Sheet %s scheduled on %s by %s"%(chkShtEvent['chkShtName'], chkShtEvent['scheduledDate'], chkShtEvent['scheduledByUser'])
				marker = createMarker(info['latitude'], info['longitude'], tooltip)
			except:
				marker = {}

			if marker: markers.append(marker)

	return markers


