security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureQuality']['enabled']: 
		canCreate = True
		canEdit = True if len(value['data'] or []) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

chkShtEvents = []

chkShtStateNames = [item for item in value['chkShtStates'] if value['chkShtStates'][str(item)]['selected']]
if len(dict(value['chkShtStates'])) != len(chkShtStateNames):
	chkShtEvents = [chkShtEvent for chkShtEvent in value['chkShtEvents'] if chkShtEvent['chkShtStateName'] in chkShtStateNames]
else:
	chkShtEvents = value['chkShtEvents']

if (value['filter'] or None) is None:
	return [{'value': chkShtEvent} for chkShtEvent in chkShtEvents]

options = []
search = value['filter'].lower()
for chkShtEvent in chkShtEvents:
	if search in str(chkShtEvent['path']).lower() or search in str(chkShtEvent['assetPath']).lower() or search in str(chkShtEvent['chkShtStateName']).lower():
		options.append({'value': chkShtEvent})

return options

